-- fixture: disabled-when
-- form: when(false)
-- policy: sql-contract-disabled-when/contract
WITH RECURSIVE packed AS MATERIALIZED (
  SELECT batch, row_kind, producer_id, file_index, task_index, match_index,
         capture_index, capture_occurrence, capture_sequence_start,
         capture_sequence_count, node, related_node, axis_kind, axis_order,
         fact_kind, document_id, mapped_document_id, start_ordinal,
         output_label, capture_label, text_value, start_byte, end_byte,
         verdict, complete, work_used, error_code, field_id, related_named,
         source_text, structural_key, named_leaf, capture_kind, capture_named,
         equality_occurrence
  FROM rerail_matches
  WHERE batch = :batch
),
batch_status AS MATERIALIZED (
  SELECT * FROM packed WHERE row_kind = 1
),
producer_status AS MATERIALIZED (
  SELECT * FROM packed WHERE row_kind = 2
),
terminal_match AS MATERIALIZED (
  SELECT * FROM packed WHERE row_kind = 3
),
capture AS MATERIALIZED (
  SELECT * FROM packed WHERE row_kind = 4
),
navigation AS MATERIALIZED (
  SELECT * FROM packed WHERE row_kind = 5
),
fact AS MATERIALIZED (
  SELECT * FROM packed WHERE row_kind = 6
),
document_map AS MATERIALIZED (
  SELECT * FROM packed WHERE row_kind = 7
),
clause_0_empty_0 AS (
  SELECT terminal_match.*, json('[]') AS bindings, '' AS choice_order
  FROM terminal_match
  WHERE 0
),
clause_0 AS (
  SELECT result.batch, result.row_kind, result.producer_id, result.file_index,
         result.task_index, result.match_index, result.capture_index,
         result.capture_occurrence, result.capture_sequence_start,
         result.capture_sequence_count, result.node, result.related_node,
         result.axis_kind, result.axis_order, result.fact_kind,
         result.document_id, result.mapped_document_id, result.start_ordinal,
         result.output_label, result.capture_label, result.text_value,
         result.start_byte, result.end_byte, result.verdict, result.complete,
         result.work_used, result.error_code, result.field_id,
         result.related_named, result.source_text, result.structural_key,
         result.named_leaf, result.capture_kind, result.capture_named,
         result.equality_occurrence, result.bindings, result.choice_order,
         0 AS clause_ordinal
  FROM clause_0_empty_0 result
  CROSS JOIN batch_status batch
  WHERE batch.complete = 1
    AND NOT EXISTS (
      SELECT 1
      FROM producer_status undecided
      WHERE undecided.complete <> 1 OR undecided.verdict IS NULL
    )
)
SELECT * FROM (SELECT * FROM clause_0)
ORDER BY clause_ordinal, file_index, node, choice_order, producer_id,
         match_index, capture_index;

